import type { DrizzleEnvSchema } from "@saflib/drizzle/env";
import type { ExpressEnvSchema } from "@saflib/express/env";
import type { NodeEnvSchema } from "@saflib/node/env";

/**
 * Environment variables for the `@saflib/ops-http` package, including inherited variables via `extends`.
 * Generated by `@saflib/env`. To update, make changes to the adjacent `env.schema.json`, navigate to the package root, and run `npm exec saf-env generate`.
 */
export interface OpsHttpEnvSchema extends DrizzleEnvSchema, ExpressEnvSchema, NodeEnvSchema {
  /**
   * Comma-separated emails that get the ops notifier's alert and new-issue emails. Unset or empty: every site admin (ADMIN_EMAILS). Doesn't change who is an admin.
   */
  OPS_NOTIFY_EMAILS?: string;
}

/**
 * `process.env` casted to the `OpsHttpEnvSchema` type.
 */
export const typedEnv = (globalThis.process ? process.env : {}) as unknown as OpsHttpEnvSchema;
